"  useEffect(() => {
    if (!posSettings?.defaultTab) return;
    const isPreOrderDisabled = !!posSettings.disableTabs?.preorder || business?.business_details?.settings?.custEnablePreOrder === false;
    if (posSettings.defaultTab === 'Dine In' && !posSettings.disableTabs?.dinein) {
      setOrderType('DINE_IN');
    } else if (posSettings.defaultTab === 'PickUp' && !posSettings.disableTabs?.pickup) {
      setOrderType('PICKUP'); setSubOrderType('PICKUP'); setBillingView('menu');
    } else if (posSettings.defaultTab === 'Delivery' && !posSettings.disableTabs?.pickup) {
      setOrderType('PICKUP'); setSubOrderType('DELIVERY'); setBillingView('menu');
    } else if (posSettings.defaultTab === 'Quick Bill' && !posSettings.disableTabs?.quickbill) {
      setOrderType('QUICK'); setBillingView('menu');
    } else if (posSettings.defaultTab === 'Pre Order' && !isPreOrderDisabled) {
      setActiveTrayTab('PreOrder');
      setBillingView('menu');
    }
  }, [posSettings?.defaultTab, posSettings?.disableTabs, business?.business_details?.settings?.custEnablePreOrder]);"

